do $$ declare t text; i int; item uuid; d text; price numeric; qty numeric; customers text[]:=array['Bodija Produce Buyers','Oke-Ado Farm Supplies','Ibadan Food Distributors','Akobo Market Traders','Oluyole Poultry Supplies']; begin t:=public.farm_api('login','{"email":"admin@folhope.demo","password":"FarmDemo2026!"}')->>'token'; for i in 0..20 loop if not exists(select 1 from farm_private.egg_collections where note='Morning collection · House A · '||i::text) then perform public.farm_api('save_egg',jsonb_build_object('good',225+(i*17)%70,'damaged',3+(i%8),'date',current_date-i,'notes','Morning collection · House A · '||i::text),t); end if; end loop; for i in 0..27 loop d:=case i%4 when 0 then 'eggs' when 1 then 'poultry' when 2 then 'fishery' else 'feedmill' end; if not exists(select 1 from farm_private.sales where sale_no='FH-1026-'||lpad(i::text,3,'0')) then select id into item from farm_private.inventory_items where sku=case d when 'eggs' then 'EGGS-GOOD' when 'poultry' then (select sku from farm_private.inventory_items where batch_id=(select id from farm_private.batches where code='POUL-001')) when 'fishery' then (select sku from farm_private.inventory_items where batch_id=(select id from farm_private.batches where code='POND-01')) else 'FEED-LAYER' end; qty:=case d when 'eggs' then 90+(i%4)*30 when 'poultry' then 4+(i%3) when 'fishery' then 20+(i%5) else 8+(i%3) end; price:=case d when 'eggs' then 220 when 'poultry' then 12500 when 'fishery' then 3800 else 950 end; perform public.farm_api('save_sale',jsonb_build_object('sale_no','FH-1026-'||lpad(i::text,3,'0'),'division',d,'date',current_date-i,'customer',customers[1+i%5],'paid',round(qty*price*(case when i%3=0 then 0.6 else 1 end),2),'lines',jsonb_build_array(jsonb_build_object('item_id',item,'quantity',qty,'unit_price',price))),t); end if; end loop; end $$; update farm_private.users set full_name=replace(full_name,' (Demo)','') where full_name like '% (Demo)'; update farm_private.sales set customer='Oluyole Produce Buyers' where sale_no like 'DEMO-SALE-%' and customer='Fictional local buyer'; update farm_private.expenses set description=replace(description,'Fictional ','') where description like 'Fictional %'; update farm_private.batches set notes='Opening production register' where notes='Fictional demonstration batch'; update farm_private.production_events set notes='Routine production update' where notes='Fictional demo acceptance scenario'; update farm_private.egg_collections set note='Morning collection · Layer house' where note='Fictional demo collection'; update farm_private.hatchery_batches set note='Completed incubation cycle' where code='HATCH-DEMO-001'; update farm_private.animals set notes='Breeding herd register' where tag='COW-DEMO-001'; select count(*) sales from farm_private.sales;
